// Deployment settings, from config.js (generated by build.py from environment variables).
// Without a sync server the app keeps progress in the browser only.
const raw = (typeof window !== 'undefined' && window.SPACEDCUBE_CONFIG) || {};

export const CONFIG = {
  supabaseUrl: String(raw.supabaseUrl || '').replace(/\/+$/, ''),
  supabaseKey: String(raw.supabaseKey || ''),
  allowSignup: !!raw.allowSignup,
  turnstileSiteKey: String(raw.turnstileSiteKey || ''),
};
